const fs = require('fs');
const http = require('http');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file into an object
const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

// Create the JSON payload
const payload = JSON.stringify(envVars);

// HTTP request options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload),
  },
};

// Make the request
const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Response:', data);
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('Secret sync successful');
    } else {
      console.error('Secret sync failed');
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error('Request error:', error.message);
  process.exit(1);
});

// Write the payload and end the request
req.write(payload);
req.end();

