// Simple test to verify the healthz endpoint works
const request = require('supertest');
const app = require('./app.js');

describe('Healthz Endpoint', () => {
  it('should return 200 with db:ok when database is healthy', async () => {
    // Note: This test assumes DATABASE_URL is properly configured
    const response = await request(app).get('/healthz');

    console.log('Response status:', response.status);
    console.log('Response body:', response.body);

    // The endpoint should either return 200 (if DB is accessible)
    // or 503 (if DB is not accessible)
    // Both are valid responses based on DB connectivity
    if (response.status === 200) {
      expect(response.body).toEqual({ db: 'ok' });
    } else if (response.status === 503) {
      expect(response.body.db).toBe('error');
      expect(response.body.message).toBe('Database connection failed');
    }
  });
});

// Simple test runner
const test = async () => {
  try {
    await describe('Healthz Endpoint', () => {
      return it('should return 200 with db:ok when database is healthy', async () => {
        const request = require('supertest');
        const app = require('./app');

        const response = await request(app).get('/healthz');
        console.log('Test Result:');
        console.log('  Status:', response.status);
        console.log('  Body:', JSON.stringify(response.body));

        if (response.status === 200) {
          console.log('  ✓ Returns 200 with db:ok when database is accessible');
        } else if (response.status === 503) {
          console.log('  ✓ Returns 503 with error when database is not accessible');
        } else {
          console.log('  ✗ Unexpected status code:', response.status);
        }
      });
    })();
  } catch (error) {
    console.error('Test error:', error);
  }
};

// Run test if this file is executed directly
if (require.main === module) {
  test();
}

