  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonData)
  }
};

// Make the request
