const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file into an object
const envVars = {};
envContent.split('\n').forEach(line => {
  const trimmed = line.trim();
  if (trimmed && !trimmed.startsWith('#')) {
    const [key, ...valueParts] = trimmed.split('=');
    if (key) {
      envVars[key] = valueParts.join('=');
    }
  }
});

// Convert to JSON
const jsonData = JSON.stringify(envVars);

// Options for the HTTP POST request
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonData)
  }
};

// Make the request
const req = http.request(options, (res) => {
  console.log(`Response status: ${res.statusCode}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Response body:', data);
    if (res.statusCode === 200) {
      console.log('Secret sync successful');
    } else {
      console.error('Secret sync failed');
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
