#!/usr/bin/env node

const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse .env file content into key-value pairs
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('=');
    if (key && value !== undefined) {
      envVars[key] = value;
    }
  }
});

console.log('Read environment variables from .env.test:');
Object.keys(envVars).forEach(key => {
  console.log(`  ${key}=${envVars[key].substring(0, 10)}...`);
});

// Prepare the POST request
const postData = JSON.stringify(envVars);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

console.log('\nSending to CI secret-sync endpoint...');

const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);
  console.log(`Status Message: ${res.statusMessage}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    if (data) {
      try {
        const response = JSON.parse(data);
        console.log('Response:', JSON.stringify(response, null, 2));
      } catch (e) {
        console.log('Response:', data);
      }
    }

    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('\n✅ CI secret-sync completed successfully');
      process.exit(0);
    } else {
      console.log('\n❌ CI secret-sync failed');
      process.exit(1);
