#!/usr/bin/env node

const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file into a JSON object
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('Read environment variables:', Object.keys(envVars));

// Prepare the request
const data = JSON.stringify(envVars);
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': data.length,
  },
};

console.log('Attempting to sync secrets to CI...');

const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response:', responseData);
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('CI secret sync successful');
      process.exit(0);
    } else {
      console.error('CI secret sync failed');
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error('Error during CI secret sync:', error.message);

  // If the CI sync endpoint is not available, we'll log it but continue
  // as this might be a local development environment
  console.log('Note: CI secret sync endpoint not available, continuing...');
  process.exit(0);
});

req.write(data);
req.end();

