#!/usr/bin/env node

const http = require('http');

const endpoints = [
  { path: '/healthz', expectedStatus: 503, description: 'DB health check (will fail without DB)' },
  { path: '/health', expectedStatus: 200, description: 'Basic health endpoint' },
  { path: '/users', expectedStatus: 200, description: 'Users endpoint' },
];

let testsPassed = 0;
let testsFailed = 0;

function testEndpoint(endpoint, callback) {
  const options = {
    hostname: 'localhost',
    port: 3000,
    path: endpoint.path,
    method: 'GET',
    headers: {
      'Accept': 'application/json',
    },
  };

  const req = http.request(options, (res) => {
    let responseData = '';
    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      const success = res.statusCode === endpoint.expectedStatus;

      if (success) {
        console.log(`✓ ${endpoint.description}`);
        console.log(`  Status: ${res.statusCode} ${res.statusMessage}`);
        testsPassed++;
      } else {
        console.log(`✗ ${endpoint.description}`);
        console.log(`  Expected: ${endpoint.expectedStatus}, Got: ${res.statusCode}`);
        testsFailed++;
      }

      callback();
    });
  });

  req.on('error', (error) => {
    console.log(`✗ ${endpoint.description} - Server not reachable: ${error.message}`);
    testsFailed++;
    callback();
  });

  req.end();
}

console.log('Testing endpoints...\n');

// Run tests sequentially
let currentTest = 0;
function runNextTest() {
  if (currentTest < endpoints.length) {
    testEndpoint(endpoints[currentTest], () => {
      currentTest++;
      setTimeout(runNextTest, 100);
    });
  } else {
    console.log('\nTest Summary:');
    console.log(`Passed: ${testsPassed}`);
    console.log(`Failed: ${testsFailed}`);
    console.log(`Total: ${endpoints.length}`);

    if (testsFailed === 0) {
      console.log('\n✓ All tests passed!');
      process.exit(0);
    } else {
      console.log('\n✗ Some tests failed');
      process.exit(1);
    }
  }
}

runNextTest();

